import { describe, expect, it } from 'vitest';
import { LockedPackage, lockedVersion, readLockfile } from './cargo-lock';
import { parseToml } from './toml';

/**
 * A lockfile with two versions of `syn`, one crate depending on each, and a git source.
 */
const LOCK: string = [
  '# This file is automatically @generated by Cargo.',
  'version = 4',
  '',
  '[[package]]',
  'name = "app"',
  'version = "0.1.0"',
  'dependencies = [',
  ' "serde",',
  ' "syn 2.0.60",',
  ' "forked",',
  ']',
  '',
  '[[package]]',
  'name = "old-macro"',
  'version = "0.3.0"',
  'dependencies = [',
  ' "syn 1.0.109",',
  ']',
  '',
  '[[package]]',
  'name = "serde"',
  'version = "1.0.200"',
  'source = "registry+https://github.com/rust-lang/crates.io-index"',
  'checksum = "ddc6f9cc94d67c0e21aaf7eda3a010fd3af78ebf6e096aa6e2e13c79749cce4f"',
  '',
  '[[package]]',
  'name = "syn"',
  'version = "1.0.109"',
  'source = "registry+https://github.com/rust-lang/crates.io-index"',
  '',
  '[[package]]',
  'name = "syn"',
  'version = "2.0.60"',
  'source = "registry+https://github.com/rust-lang/crates.io-index"',
  '',
  '[[package]]',
  'name = "forked"',
  'version = "0.9.0"',
  'source = "git+https://github.com/me/forked.git?tag=v1#0123456789abcdef"',
].join('\n');

describe('readLockfile', () => {
  it('readLockfile_aLockfile_readsEveryPackageWithItsSource', () => {
    // Arrange
    const document: ReturnType<typeof parseToml> = parseToml(LOCK);

    // Act
    const packages: readonly LockedPackage[] = readLockfile(document);

    // Assert
    expect(packages).toHaveLength(6);
    expect(packages[0]).toEqual({
      name: 'app',
      version: '0.1.0',
      source: null,
      dependencies: ['serde', 'syn 2.0.60', 'forked'],
    });
    expect(packages[5].source).toContain('git+');
  });
});

describe('lockedVersion', () => {
  const packages: readonly LockedPackage[] = readLockfile(parseToml(LOCK));

  it('lockedVersion_severalVersionsLocked_readsTheOneTheCrateNames', () => {
    // Arrange
    const app: { name: string; version: string } = { name: 'app', version: '0.1.0' };
    const old: { name: string; version: string } = { name: 'old-macro', version: '0.3.0' };

    // Act
    const forApp: string | null = lockedVersion(packages, app, 'syn');
    const forOld: string | null = lockedVersion(packages, old, 'syn');

    // Assert
    expect(forApp).toBe('2.0.60');
    expect(forOld).toBe('1.0.109');
  });

  it('lockedVersion_oneVersionLocked_readsItByName', () => {
    // Arrange
    const app: { name: string; version: string } = { name: 'app', version: '0.1.0' };

    // Act
    const serde: string | null = lockedVersion(packages, app, 'serde');
    const forked: string | null = lockedVersion(packages, app, 'forked');

    // Assert
    expect(serde).toBe('1.0.200');
    expect(forked).toBe('0.9.0');
  });

  it('lockedVersion_crateNotInTheLockAndSeveralVersions_answersNothingRatherThanGuessing', () => {
    // Arrange
    const stranger: { name: string; version: null } = { name: 'stranger', version: null };

    // Act
    const syn: string | null = lockedVersion(packages, stranger, 'syn');

    // Assert
    expect(syn).toBeNull();
  });

  it('lockedVersion_notLockedAtAll_answersNull', () => {
    // Arrange
    const app: { name: string; version: string } = { name: 'app', version: '0.1.0' };

    // Act
    const missing: string | null = lockedVersion(packages, app, 'tokio');

    // Assert
    expect(missing).toBeNull();
  });
});
